<?php
declare(strict_types=1);

require_once __DIR__.'/../lib/safety_vote_live_results.php';

function svlr_questions(int$versionId):array{$rows=db_rows("SELECT q.id,q.QuestionCode questionCode,q.QuestionType questionType,q.Title title,q.MaxSelections maxSelections,o.id optionId,o.OptionCode optionCode,o.Label label,o.Description description,o.FileID fileId FROM SafetyVote_Questions q LEFT JOIN SafetyVote_Options o ON o.QuestionID=q.id AND o.Status='Active' WHERE q.CampaignVersionID=? AND q.Status='Active' ORDER BY q.SortOrder,q.id,o.SortOrder,o.id",[$versionId]);$out=[];foreach($rows as$row){$id=(int)$row['id'];if(!isset($out[$id]))$out[$id]=['id'=>$id,'questionCode'=>$row['questionCode'],'questionType'=>$row['questionType'],'title'=>$row['title'],'maxSelections'=>(int)$row['maxSelections'],'options'=>[]];if(!empty($row['optionId']))$out[$id]['options'][]=['id'=>(int)$row['optionId'],'optionCode'=>$row['optionCode'],'label'=>$row['label'],'description'=>$row['description']?:null,'fileId'=>!empty($row['fileId'])?(int)$row['fileId']:null];}return array_values($out);}
function svlr_data(array$c,bool$admin):array{$questions=svlr_questions((int)$c['CurrentVersionID']);$supported=svlr_supported((string)$c['CampaignType'],$questions);if(!$supported['ok'])json_response(['success'=>false,'code'=>$supported['code'],'message'=>'This campaign or question configuration does not support Live Leaderboard.'],409);$counts=db_row("SELECT COUNT(*) totalAcceptedVotes FROM SafetyVote_Ballots WHERE CampaignVersionID=? AND Status='Accepted'",[$c['CurrentVersionID']]);$total=(int)($counts['totalAcceptedVotes']??0);$threshold=max(SVLR_SERVER_MINIMUM_THRESHOLD,(int)$c['PrivacyThreshold'],(int)($c['LiveLeaderboardPrivacyThreshold']??0));$empty=$total===0;$below=$total<$threshold;$status=$empty?'empty':($below?'threshold_not_met':'available');$base=['status'=>$status,'campaignId'=>(int)$c['id'],'campaignStatus'=>$c['Status'],'config'=>['enabled'=>true,'topN'=>(int)$c['LiveLeaderboardTopN'],'scoreMode'=>$c['LiveLeaderboardScoreMode'],'visibility'=>$c['LiveLeaderboardVisibility'],'refreshSeconds'=>(int)$c['LiveLeaderboardRefreshSeconds'],'privacyThreshold'=>$threshold],'totalAcceptedVotes'=>$empty?0:($below?null:$total),'minimumRequired'=>$threshold,'scoreDisclosure'=>$empty?'zero':($below?'masked':'aggregate'),'lastCalculatedAt'=>date(DATE_ATOM),'rankingPolicy'=>'competition','denominatorPolicy'=>'valid_option_answers_including_abstain','provisional'=>true];if($below)return$base+['questions'=>svlr_masked_questions($questions,(int)$c['LiveLeaderboardTopN'],$empty)];$answers=db_rows("SELECT a.QuestionID,a.OptionID FROM SafetyVote_BallotAnswers a JOIN SafetyVote_Ballots b ON b.id=a.BallotID AND b.CampaignVersionID=? AND b.Status='Accepted' JOIN SafetyVote_Questions q ON q.id=a.QuestionID AND q.CampaignVersionID=b.CampaignVersionID AND q.Status='Active' JOIN SafetyVote_Options o ON o.id=a.OptionID AND o.QuestionID=q.id AND o.Status='Active'",[$c['CurrentVersionID']]);$aggregate=svlr_aggregate($questions,$answers,(int)$c['LiveLeaderboardTopN']);if(!$admin)foreach($aggregate as&$question)$question['options']=$question['summary'];unset($question);return$base+['questions'=>$aggregate];}
function handle_safety_vote_live_results_routes(string$method,string$path):bool{
    $settings=route_params($path,'/safety-vote/admin/campaigns/:id/live-settings');
    $admin=route_params($path,'/safety-vote/admin/campaigns/:id/live-results');
    $userRoute=route_params($path,'/safety-vote/campaigns/:id/live-results');
    if($settings===null&&$admin===null&&$userRoute===null)return false;
    $user=require_user();sv_require_schema();
    if($settings!==null&&$method==='PUT'){
        sv_require_permission($user,'SAFETY_VOTE_MANAGE');$id=sv_positive_int($settings['id']);$body=json_body();$expected=sv_positive_int($body['versionRowVersion']??null);$enabled=$body['enabled']??null;$reason=sv_clean($body['reason']??'',500);
        if(!$id||!$expected||!is_bool($enabled)||mb_strlen($reason)<10)json_response(['success'=>false,'code'=>'VALIDATION_FAILED','message'=>'Campaign ID, versionRowVersion, enabled and a reason of at least 10 characters are required.'],400);
        $pdo=db();$pdo->beginTransaction();
        try{
            $stmt=$pdo->prepare("SELECT c.id,c.CampaignCode,c.Status,c.CurrentVersionID,v.CampaignType,v.PrivacyMode,v.LiveLeaderboardEnabled,v.LiveLeaderboardTopN,v.LiveLeaderboardScoreMode,v.LiveLeaderboardVisibility,v.LiveLeaderboardRefreshSeconds,v.LiveLeaderboardPrivacyThreshold,v.RowVersion VersionRowVersion FROM SafetyVote_Campaigns c JOIN SafetyVote_CampaignVersions v ON v.id=c.CurrentVersionID WHERE c.id=? AND c.Status<>'Voided' LIMIT 1 FOR UPDATE");$stmt->execute([$id]);$c=$stmt->fetch();
            if(!$c){$pdo->rollBack();json_response(['success'=>false,'code'=>'CAMPAIGN_NOT_FOUND','message'=>'Campaign was not found.'],404);}
            if($c['Status']!=='Open'){$pdo->rollBack();json_response(['success'=>false,'code'=>'LIVE_SETTINGS_CAMPAIGN_NOT_OPEN','message'=>'Operational Live settings can be changed only while the campaign is open.'],409);}
            if($c['CampaignType']!=='popular_vote'||$c['PrivacyMode']==='secret_ballot'){$pdo->rollBack();json_response(['success'=>false,'code'=>'LIVE_RESULTS_UNSUPPORTED_CAMPAIGN_TYPE','message'=>'This campaign does not support Live Leaderboard.'],409);}
            if((int)$c['VersionRowVersion']!==$expected){$pdo->rollBack();json_response(['success'=>false,'code'=>'VERSION_CONFLICT','message'=>'Campaign version changed. Reload before updating Live settings.'],409);}
            $confirmation=($enabled?'ENABLE':'DISABLE').' LIVE '.$c['CampaignCode'];if((string)($body['confirmation']??'')!==$confirmation){$pdo->rollBack();json_response(['success'=>false,'code'=>'LIVE_SETTINGS_CONFIRMATION_REQUIRED','message'=>'Type '.$confirmation.' exactly.'],400);}
            if($enabled){$supported=svlr_supported((string)$c['CampaignType'],svlr_questions((int)$c['CurrentVersionID']));if(!$supported['ok']){$pdo->rollBack();json_response(['success'=>false,'code'=>$supported['code'],'message'=>'This campaign or question configuration does not support Live Leaderboard.'],409);}}
            $previous=(int)$c['LiveLeaderboardEnabled']===1;$stmt=$pdo->prepare('UPDATE SafetyVote_CampaignVersions SET LiveLeaderboardEnabled=?,UpdatedBy=?,RowVersion=RowVersion+1 WHERE id=? AND RowVersion=?');$stmt->execute([$enabled?1:0,sv_actor($user),(int)$c['CurrentVersionID'],$expected]);if($stmt->rowCount()!==1){$pdo->rollBack();json_response(['success'=>false,'code'=>'VERSION_CONFLICT','message'=>'Campaign version changed. Reload before updating Live settings.'],409);}
            $stmt=$pdo->prepare('INSERT INTO SafetyVote_AuditLogs(CampaignID,CampaignVersionID,ActorEmployeeID,ActorRole,Action,TargetType,TargetID,StatusCode,BoundedDetail,MetadataJson,IPAddress,UserAgent) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)');$stmt->execute([$id,(int)$c['CurrentVersionID'],sv_actor($user),sv_role($user),'SAFETY_VOTE_LIVE_SETTINGS_UPDATE','SafetyVote_CampaignVersion',(string)$c['CurrentVersionID'],200,$reason,json_encode(['previousEnabled'=>$previous,'enabled'=>$enabled,'campaignStatus'=>$c['Status'],'ballotsPreserved'=>true,'answersPreserved'=>true,'visibility'=>$c['LiveLeaderboardVisibility'],'topN'=>(int)$c['LiveLeaderboardTopN'],'privacyThreshold'=>(int)$c['LiveLeaderboardPrivacyThreshold']],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),(string)($_SERVER['REMOTE_ADDR']??''),mb_substr((string)($_SERVER['HTTP_USER_AGENT']??''),0,255)]);
            $pdo->commit();json_response(['success'=>true,'data'=>['campaignId'=>$id,'versionId'=>(int)$c['CurrentVersionID'],'versionRowVersion'=>$expected+1,'enabled'=>$enabled,'previousEnabled'=>$previous,'config'=>['topN'=>(int)$c['LiveLeaderboardTopN'],'scoreMode'=>$c['LiveLeaderboardScoreMode'],'visibility'=>$c['LiveLeaderboardVisibility'],'refreshSeconds'=>(int)$c['LiveLeaderboardRefreshSeconds'],'privacyThreshold'=>(int)$c['LiveLeaderboardPrivacyThreshold']],'ballotsPreserved'=>true,'answersPreserved'=>true]]);return true;
        }catch(Throwable$error){if($pdo->inTransaction())$pdo->rollBack();error_log('[safety-vote] Live settings update failed: '.$error->getMessage());json_response(['success'=>false,'code'=>'LIVE_SETTINGS_UPDATE_FAILED','message'=>'Unable to update Live Leaderboard settings.'],500);}
    }
    if($settings!==null||$method!=='GET')return false;
    sv_require_permission($user,$admin!==null?'SAFETY_VOTE_RESULT_VIEW':'SAFETY_VOTE_VIEW');$id=sv_positive_int(($admin??$userRoute)['id']);$c=$id?db_row('SELECT c.id,c.CampaignCode,c.Status,c.CurrentVersionID,c.OpenedAt,c.ClosedAt,v.CampaignType,v.PrivacyThreshold,v.LiveLeaderboardEnabled,v.LiveLeaderboardTopN,v.LiveLeaderboardScoreMode,v.LiveLeaderboardVisibility,v.LiveLeaderboardRefreshSeconds,v.LiveLeaderboardPrivacyThreshold FROM SafetyVote_Campaigns c JOIN SafetyVote_CampaignVersions v ON v.id=c.CurrentVersionID WHERE c.id=? AND c.Status<>\'Voided\' LIMIT 1',[$id]):null;
    if(!$c)json_response(['success'=>false,'code'=>'CAMPAIGN_NOT_FOUND','message'=>'Campaign was not found.'],404);if(!(int)$c['LiveLeaderboardEnabled'])json_response(['success'=>false,'code'=>'LIVE_RESULTS_DISABLED','message'=>'Live Leaderboard is disabled for this campaign.'],409);if($c['Status']!=='Open')json_response(['success'=>false,'code'=>'LIVE_RESULTS_CAMPAIGN_NOT_OPEN','message'=>'Live results are available only while the campaign is open. Use the official result workflow after closing.'],409);
    if($admin===null){if($c['LiveLeaderboardVisibility']==='admin_only')json_response(['success'=>false,'code'=>'LIVE_RESULTS_ADMIN_ONLY','message'=>'Live results are available to administrators only.'],403);$eligible=db_row("SELECT e.id FROM SafetyVote_EligibilitySnapshots s JOIN SafetyVote_EligibleVoters e ON e.SnapshotID=s.id WHERE s.CampaignVersionID=? AND s.Status='frozen' AND e.EmployeeID=? AND e.EligibilityState='eligible' LIMIT 1",[$c['CurrentVersionID'],sv_actor($user)]);if(!$eligible)json_response(['success'=>false,'code'=>'CAMPAIGN_NOT_ELIGIBLE','message'=>'You are not eligible for this campaign.'],403);if($c['LiveLeaderboardVisibility']==='after_submit'&&!db_row("SELECT id FROM SafetyVote_Participation WHERE CampaignVersionID=? AND EmployeeID=? AND State='submitted' LIMIT 1",[$c['CurrentVersionID'],sv_actor($user)]))json_response(['success'=>false,'code'=>'LIVE_RESULTS_SUBMISSION_REQUIRED','message'=>'Submit your ballot before viewing live results.'],403);}
    json_response(['success'=>true,'data'=>svlr_data($c,$admin!==null)]);return true;
}
